import sys
sys.path.insert(0, '/tmp/probe')
import png

def load(path):
    return png.load(path)

def dump(path, thresh=128):
    """Print ASCII map of dark pixels with coordinates."""
    w,h,ch,ct,px,chunks = png.load(path)
    print(f"size {w}x{h}")
    for y in range(h):
        row = []
        for x in range(w):
            off = (y*w+x)*ch
            r,g,b = px[off],px[off+1],px[off+2]
            lum = (r+g+b)//3
            row.append('#' if lum < thresh else ('+' if lum < 200 else '.'))
        line = ''.join(row)
        if '#' in line or '+' in line:
            print(f"{y:3d} {line}")

def colors(path):
    from collections import Counter
    w,h,ch,ct,px,chunks = png.load(path)
    c = Counter()
    for i in range(0, len(px), ch):
        c[px[i:i+3]] += 1
    for col,n in c.most_common():
        print(col.hex() if isinstance(col,bytes) else col, n)

if __name__ == '__main__':
    import os
    path = sys.argv[1]
    if len(sys.argv) > 2 and sys.argv[2] == '-c':
        colors(path)
    else:
        dump(path)

